def get_number(prompt):
    """Get a number as input from the user."""
    while True:
        try:
            number = float(input(prompt))
            return number
        except ValueError:
            print("That's not a valid number. Please try again.")

def get_operation():
    """Get an arithmetic operation as input from the user."""
    operations = {"+": add, "-": subtract, "*": multiply, "/": divide}
    while True:
        operation = input("Enter an operation (+, -, *, /): ").strip()
        if operation in operations:
            return operation, operations[operation]
        else:
            print("That's not a valid operation. Please try again.")

def perform_operation(num1, num2, operation):
    """Perform the given operation on two numbers and return the result."""
    return operation(num1, num2)

